-- 本地事务验收；所有测试订单、地址、凭证、运价修改最后回滚。
begin;
create temporary table qa_distance_results(test text,result text) on commit drop;
grant select,insert on qa_distance_results to authenticated;
select set_config('qa.distance.m',(select id::text from public.profiles where role='merchant' and is_active limit 1),true);
select set_config('qa.distance.a',(select id::text from public.profiles where role='admin' and is_active limit 1),true);
select set_config('qa.distance.w',(select id::text from public.profiles where role='warehouse_operator' and is_active limit 1),true);
insert into public.orders(order_no,merchant_id,warehouse_id,status,transport_leg,route_code,route_name,destination_country,destination_city,destination_address,recipient_name,recipient_phone,origin_warehouse_name,origin_warehouse_address,destination_overseas_warehouse_id,destination_warehouse_snapshot,overseas_received_at,overseas_warehouse,parcel_count)
select 'QA-DISTANCE-'||gen_random_uuid(),current_setting('qa.distance.m')::uuid,w.id,'shipped','first_mile','ID-SEA','QA海运','印度尼西亚',ow.city,ow.address_line,ow.contact_name,ow.contact_phone,'QA深圳','QA深圳测试仓',ow.id,to_jsonb(ow),now(),ow.name,2 from public.warehouses w cross join public.overseas_warehouses ow where w.code='SZ-LG-01' and ow.code='ID-JKT-TEST';
select set_config('qa.distance.head',(select id::text from public.orders where order_no like 'QA-DISTANCE-%' limit 1),true);
insert into public.fees(order_id,fee_breakdown_version,shipping_fee,handling_fee,total_amount,confirmed_at,locked_at) values(current_setting('qa.distance.head')::uuid,3,60,18,78,now(),now());
insert into public.payments(order_id,merchant_id,amount,status,provider) values(current_setting('qa.distance.head')::uuid,current_setting('qa.distance.m')::uuid,78,'paid','test_transfer_review');
set local role authenticated;
do $$
declare m uuid:=current_setting('qa.distance.m')::uuid;a uuid:=current_setting('qa.distance.a')::uuid;w uuid:=current_setting('qa.distance.w')::uuid;
 h uuid:=current_setting('qa.distance.head')::uuid;z public.last_mile_zones;old_z public.last_mile_zones;t public.orders;again public.orders;f public.fees;cfg jsonb;err text;ac public.payment_receiving_accounts;r public.payment_receipts;n text:=gen_random_uuid()::text;path text;addr_count int;
 recipient jsonb:='{"recipient_name":"QA消费者","recipient_phone":"TEST-PHONE","country":"印度尼西亚","city":"Jakarta","address_line":"仅限本地测试地址，禁止寄件"}';
begin
 perform set_config('request.jwt.claim.sub',m::text,true);
 if (select count(*) from public.last_mile_zones)<>6 then raise exception '测试地区数量错误';end if;
 select * into z from public.last_mile_zones where code='JABODETABEK';
 if public.last_mile_distance_amount(20,10,0.5,0)<>20 or public.last_mile_distance_amount(20,10,0.5,10)<>20 or public.last_mile_distance_amount(20,10,0.5,30)<>30 or public.last_mile_distance_amount(20,10,0.5,10.01)<>20.01 then raise exception '距离公式或精度错误';end if;
 err:=null;begin perform public.last_mile_distance_amount(20,10,0.5,'NaN');exception when others then err:=sqlerrm;end;if err is null then raise exception 'NaN被接受';end if;
 err:=null;begin perform public.last_mile_distance_amount(20,10,0.5,-1);exception when others then err:=sqlerrm;end;if err is null then raise exception '负距离被接受';end if;
 err:=null;begin perform public.last_mile_distance_amount(20,10,0.5,1.001);exception when others then err:=sqlerrm;end;if err is null then raise exception '过多小数被接受';end if;
 insert into qa_distance_results values('六地区种子、起步区间、超公里、金额舍入及无效输入拒绝','PASS');
 cfg:=to_jsonb(z);old_z:=z;
 err:=null;begin perform public.admin_save_last_mile_zone(z.id,z.updated_at,cfg);exception when others then err:=sqlerrm;end;if err is null then raise exception '商家可维护运价';end if;
 select count(*) into addr_count from public.merchant_addresses;
 err:=null;begin perform public.merchant_create_distance_last_mile(h,recipient,z.id,z.updated_at-interval '1s');exception when others then err:=sqlerrm;end;if err is null then raise exception '旧版本预估可下单';end if;
 if (select count(*) from public.merchant_addresses)<>addr_count then raise exception '失败下单残留地址';end if;
 t:=public.merchant_create_distance_last_mile(h,recipient,z.id,z.updated_at);again:=public.merchant_create_distance_last_mile(h,'{}',null,null);
 select * into f from public.fees where order_id=t.id;
 if t.id<>again.id or t.delivery_zone_id<>z.id or f.estimated_total<>30 or f.total_amount is not null or f.confirmed_at is not null or f.pricing_snapshot->>'type'<>'last_mile_distance' then raise exception '预估、快照、幂等或未确认金额错误';end if;
 err:=null;begin perform public.warehouse_quote_last_mile_distance(t.id,z.id,50,'QA核对',z.updated_at);exception when others then err:=sqlerrm;end;if err is null then raise exception '商家可确认尾程价格';end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 if exists(select 1 from public.orders where id=t.id) then raise exception '未授权用户可读取订单';end if;
 err:=null;begin perform public.merchant_create_distance_last_mile(h,recipient,z.id,z.updated_at);exception when others then err:=sqlerrm;end;if err is null then raise exception '跨商家可建尾程';end if;
 insert into qa_distance_results values('地区下单预估30、未确认不收款、失败回滚、重试不重复与角色隔离','PASS');
 perform set_config('request.jwt.claim.sub',a::text,true);
 z:=public.admin_save_last_mile_zone(z.id,z.updated_at,cfg||'{"base_fee":25}');
 if z.updated_at=old_z.updated_at then raise exception '同事务运价版本未变化';end if;
 err:=null;begin perform public.admin_save_last_mile_zone(z.id,old_z.updated_at,cfg);exception when others then err:=sqlerrm;end;if err is null then raise exception '过期运价可覆盖';end if;
 err:=null;begin perform public.admin_save_last_mile_zone(z.id,z.updated_at,cfg||'{"included_distance_km":-1}');exception when others then err:=sqlerrm;end;if err is null then raise exception '负起步里程可保存';end if;
 perform set_config('request.jwt.claim.sub',w::text,true);
 err:=null;begin perform public.warehouse_quote_last_mile_distance(t.id,z.id,50,'QA核对',old_z.updated_at);exception when others then err:=sqlerrm;end;if err is null then raise exception '旧版价格可确认';end if;
 err:=null;begin perform public.warehouse_quote_last_mile(t.id,1,'QA绕过');exception when others then err:=sqlerrm;end;if err is null then raise exception '手工金额可绕过地区计费';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 z:=public.admin_save_last_mile_zone(z.id,z.updated_at,to_jsonb(z)||'{"is_active":false}');
 perform set_config('request.jwt.claim.sub',w::text,true);
 err:=null;begin perform public.warehouse_quote_last_mile_distance(t.id,z.id,50,'QA核对',z.updated_at);exception when others then err:=sqlerrm;end;if err is null then raise exception '停用地区可确认';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);z:=public.admin_save_last_mile_zone(z.id,z.updated_at,cfg);
 perform set_config('request.jwt.claim.sub',w::text,true);
 f:=public.warehouse_quote_last_mile_distance(t.id,z.id,50,'QA采用测试距离50km',z.updated_at);
 if f.total_amount<>40 or f.last_mile_fee<>40 or f.shipping_fee<>0 or f.handling_fee<>0 or (select status from public.orders where id=t.id)<>'awaiting_payment' or f.pricing_snapshot->>'distance_km'<>'50' then raise exception '仓库距离核价错误';end if;
 err:=null;begin perform public.warehouse_quote_last_mile_distance(t.id,z.id,60,'QA重算',z.updated_at);exception when others then err:=sqlerrm;end;if err is null then raise exception '已确认可重算';end if;
 insert into qa_distance_results values('运营改价与停用、版本冲突拒绝、禁止手工绕过、仓库50km核价40并锁定','PASS');
 perform set_config('request.jwt.claim.sub',m::text,true);
 select * into f from public.fees where order_id=t.id;if f.total_amount<>40 then raise exception '商家读取金额不一致';end if;
 select * into ac from public.payment_receiving_accounts where singleton;
 path:=m||'/'||t.id||'/'||gen_random_uuid()||'.png';insert into storage.objects(bucket_id,name,metadata) values('payment-proofs',path,'{"size":100,"mimetype":"image/png"}');
 r:=public.merchant_submit_payment_receipt(t.id,path,'QA付款',null,now(),'仅本地模拟',ac.updated_at);
 if r.amount<>40 then raise exception '尾程凭证金额不一致';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 r:=public.admin_review_payment_receipt(r.id,true,40,'QA-DIST-'||n,'QA审核',true);
 z:=public.admin_save_last_mile_zone(z.id,z.updated_at,cfg||'{"base_fee":99}');
 if (select total_amount from public.fees where order_id=t.id)<>40 or (select amount from public.payments where order_id=t.id)<>40 or (select total_amount from public.fees where order_id=h)<>78 or (select pricing_snapshot->'zone'->>'base_fee' from public.fees where order_id=t.id)::numeric<>20 then raise exception '改价污染历史尾程、头程或付款金额';end if;
 perform set_config('request.jwt.claim.sub',w::text,true);
 perform public.warehouse_pack_order(t.id,'QA-BOX','仅本地测试');perform public.warehouse_ship_order(t.id,'QA承运商','QA-'||n);perform public.warehouse_complete_delivery(t.id,'QA本地模拟签收');
 if (select status from public.orders where id=t.id)<>'delivered' then raise exception '尾程闭环未完成';end if;
 insert into qa_distance_results values('商家与仓库同价40、独立付款审核、改价保留历史快照、出库配送签收，头程78不变','PASS');
 perform set_config('request.jwt.claim.sub',a::text,true);
 z:=public.admin_save_last_mile_zone(null,null,cfg||'{"name":"QA新增地区"}');
 if z.name<>'QA新增地区' then raise exception '新增地区失败';end if;
 insert into qa_distance_results values('运营可新增地区运价','PASS');
end $$;
reset role;
select * from qa_distance_results;
rollback;
